    "quickstart.activateTitle": "Activate your Platho account",
    "quickstart.activateWhy": "Activation registers your messaging keys on-chain (a one-time fee from your wallet). After it you can send and receive private messages. It needs a funded wallet - do it now, or later from the Profile tab.",
    "quickstart.activationNeedsChecking": "Activation needs {fee} GRAM · balance checking…",
    "quickstart.addKeyTitle": "Add a TON Center key",
    "quickstart.addKeyWhy": "Your own free TON Center API key (10 requests/sec + the message indexer) makes Platho faster and avoids shared rate limits. Optional - without it Platho uses the shared public TON Center endpoint, just slower. Get one in ~10 seconds from the @toncenter Telegram bot, then paste it here.",
    "quickstart.backupKeyTitle": "Back up your wallet key",
    "quickstart.backupKeyWhy": "Two ways to keep the wallet safe. Do at least one.",
    "quickstart.keyFilePlateNote": "Browser storage can be cleared - especially on iPhone Safari - which would wipe your wallet from this device. Save the encrypted wallet-key file now; it is protected by your password and also carries your TON Center key, so you can restore everything on any device.",
    "quickstart.seedPlateNote": "A recovery phrase is 24 words. Written on paper it lives outside this device and outside any password: even if you forget the password and lose the file, those words bring the wallet and its funds back on any device.",
    "quickstart.saveSeedAction": "Save recovery phrase",
    "quickstart.backupNeedsOne": "Save the wallet key file, or type SAVED to confirm you wrote the words down. Either one is enough.",
