    "quickstart.activateAction": "Активировать аккаунт",
    "quickstart.activateTitle": "Активируйте аккаунт Platho",
    "quickstart.activateWhy": "Активация регистрирует ваши ключи для сообщений в блокчейне (разовая комиссия из кошелька). После неё можно отправлять и получать приватные сообщения. Нужен пополненный кошелёк — сделайте это сейчас или позже на вкладке «Профиль».",
    "quickstart.activationNeedsChecking": "Для активации нужно {fee} GRAM · проверка баланса…",
    "quickstart.addKeyTitle": "Добавьте ключ TON Center",
    "quickstart.addKeyWhy": "Ваш собственный бесплатный API-ключ TON Center (10 запросов/сек + индексатор сообщений) ускоряет Platho и снимает общие ограничения по частоте. Необязательно — без него Platho работает через общий публичный эндпойнт TON Center, просто медленнее. Получите ключ за ~10 секунд у Telegram-бота @toncenter и вставьте его сюда.",
    "quickstart.backupKeyTitle": "Сохраните ключ кошелька",
    "quickstart.backupKeyWhy": "Два способа сохранить доступ к кошельку. Сделайте хотя бы один.",
    "quickstart.keyFilePlateNote": "Хранилище браузера можно очистить — особенно в Safari на iPhone — что сотрёт кошелёк с этого устройства. Сохраните зашифрованный файл ключа кошелька сейчас; он защищён вашим паролем и также содержит ваш ключ TON Center, так что вы сможете восстановить всё на любом устройстве.",
    "quickstart.seedPlateNote": "Мнемоническая фраза — это 24 слова. Записанная на бумаге, она живёт вне этого устройства и вне любых паролей: даже если вы забудете пароль и потеряете файл, эти слова вернут кошелёк и его средства на любом устройстве.",
    "quickstart.saveSeedAction": "Сохранить мнемоническую фразу",
    "quickstart.backupNeedsOne": "Сохраните файл ключа или введите SAVED, подтверждая, что записали слова. Достаточно любого.",
    "quickstart.balanceActivationNeeds": "Баланс кошелька: {balance} GRAM · для активации нужно {fee} GRAM",
    "quickstart.balanceChecking": "Баланс: проверка…",
