    "docs.unavailable": "文档不可用",
    "install.body": "Platho 是一个静态 PWA。安装后，应用外壳、文档和有限的本地加密历史记录会缓存在本设备上。缓存有助于恢复，但它并非通用备份。合约读取、经验证的公开动态更新、消息历史检索和发送交易仍需网络访问。Platho 不使用任何能读取你消息或持有你密钥的服务器账户。",
    "install.bodyInstructions": "如果 Platho 已安装，请使用地址栏、启动器、程序坞或应用列表中的打开应用按钮。如果尚未安装，请使用浏览器菜单中的安装操作。浏览器并不总会向网页公开已安装应用的状态。",
    "install.bodyIos": "Safari 不允许 Platho 直接打开安装面板。请点按分享，选择添加到主屏幕，然后从 Home Screen 启动 Platho。它会在一个更简洁的应用窗口中运行，比普通的 Safari 标签页更稳固，但仍请保留你的加密钱包密钥备份。",
    "install.bodyOpenInApp": "你的浏览器已将 Platho 识别为已安装的应用。请使用地址栏、启动器、程序坞或应用列表中的打开应用按钮，切换到已安装的应用窗口。",
    "install.bodyPrompt": "Platho 是一个静态 PWA。安装后，应用外壳、文档和有限的本地加密历史缓存会存储在本设备上。缓存有助于恢复，但它并非通用备份。合约读取、经验证的公开动态更新、消息历史检索和发送交易仍需网络访问。Platho 不使用任何能读取你消息或持有你密钥的服务器账户。",
    "install.closePrompt": "关闭安装提示",
    "install.gotIt": "知道了",
    "install.help": "如果你的浏览器未显示安装面板，请使用浏览器菜单并选择安装应用或添加到主屏幕。",
    "install.helpInstalled": "Platho 已安装在本设备上。请从主屏幕、启动器、程序坞或应用列表中打开它。",
    "install.helpIos": "Home Screen 模式是推荐的 iPhone 模式。如果找不到添加到主屏幕，请确认此页面是在 Safari 中打开，而非在其他应用的浏览器内。",
    "install.helpOpenInApp": "浏览器未公开可靠的网页 API，使 Platho 无法直接从此页面启动已安装的应用。",
    "install.helpPrompt": "下一步会打开你浏览器的安装面板。如果你取消，安装按钮仍会留在这里，方便你找到手动安装路径。",
