    "quickstart.activateTitle": "激活你的 Platho 账户",
    "quickstart.activateWhy": "激活会将你的消息密钥注册到链上（从钱包一次性收费）。之后你就能收发私密消息。这需要一个有资金的钱包——现在做，或稍后从个人资料标签页做。",
