    "quickstart.addKeyTitle": "添加 TON Center 密钥",
    "quickstart.addKeyWhy": "你自己的免费 TON Center API 密钥（10 次请求/秒 + 消息索引器）让 Platho 更快，并避免共享速率限制。可选——没有它 Platho 会使用共享的公共 TON Center 端点，只是更慢。约 10 秒即可从 @toncenter Telegram 机器人获取一个，然后粘贴到这里。",
    "quickstart.backupKeyTitle": "备份你的钱包密钥",
