    "docs.lead": "Notas del protocolo y modelo de la aplicación.",
    "docs.loading": "Cargando",
    "docs.unavailable": "Documento no disponible",
    "install.body": "Platho es una PWA estática. Tras la instalación, el núcleo de la app, la documentación y un historial cifrado local acotado quedan en caché en este dispositivo. La caché mejora la recuperación, pero no es una copia de seguridad universal. Aún se necesita acceso a la red para lecturas del contrato, actualizaciones verificadas del feed público, recuperación del historial de mensajes y envío de transacciones. Platho no usa una cuenta de servidor que pueda leer tus mensajes ni guardar tus claves.",
    "install.bodyInstructions": "Si Platho ya está instalado, usa el botón de abrir app en la barra de direcciones, el lanzador, el dock o la lista de apps. Si aún no está instalado, usa la acción de instalar del menú del navegador. Los navegadores no siempre exponen a las páginas web el estado de app instalada.",
    "install.bodyIos": "Safari no permite que Platho abra la hoja de instalación directamente. Toca Compartir, elige Añadir a pantalla de inicio y luego abre Platho desde la Home Screen. Se ejecuta en una ventana de app más limpia y es menos frágil que una pestaña normal de Safari, pero conserva de todos modos la copia de seguridad cifrada de tu clave de billetera.",
    "install.bodyOpenInApp": "Tu navegador ya reconoce a Platho como una app instalada. Usa el botón de abrir app en la barra de direcciones, el lanzador, el dock o la lista de apps para pasar a la ventana de la app instalada.",
    "install.bodyPrompt": "Platho es una PWA estática. Tras la instalación, el núcleo de la app, la documentación y la caché del historial cifrado local acotado se almacenan en este dispositivo. La caché mejora la recuperación, pero no es una copia de seguridad universal. Aún se necesita acceso a la red para lecturas del contrato, actualizaciones verificadas del feed público, recuperación del historial de mensajes y envío de transacciones. Platho no usa una cuenta de servidor que pueda leer tus mensajes ni guardar tus claves.",
    "install.closePrompt": "Cerrar aviso de instalación",
    "install.gotIt": "Entendido",
    "install.help": "Si tu navegador no muestra la hoja de instalación, usa el menú del navegador y elige Instalar app o Añadir a pantalla de inicio.",
    "install.helpInstalled": "Platho ya está instalado en este dispositivo. Ábrelo desde tu pantalla de inicio, el lanzador, el dock o la lista de apps.",
    "install.helpIos": "El modo Home Screen es el modo recomendado para iPhone. Si falta Añadir a pantalla de inicio, asegúrate de que esta página esté abierta en Safari y no dentro del navegador de otra app.",
    "install.helpOpenInApp": "Los navegadores no exponen una API web fiable que permita a Platho abrir la app instalada directamente desde esta página.",
    "install.helpPrompt": "El siguiente paso abre la hoja de instalación de tu navegador. Si la cancelas, el botón de instalar permanece aquí para que aún puedas encontrar la vía manual.",
    "install.helpTextAndroid": "En Chrome de Android, abre el menú del navegador y elige Instalar app o Añadir a pantalla de inicio.",
    "install.helpTextDesktop": "En Chrome o Edge, usa el ícono de instalar de la barra de direcciones o el menú del navegador: Apps / Instalar este sitio.",
    "install.helpTextIos": "En iPhone o iPad, abre esta página en Safari, toca Compartir y luego Añadir a pantalla de inicio.",
    "install.howToInstallIphone": "Cómo instalar en iPhone",
