    "quickstart.activateAction": "Activar cuenta",
    "quickstart.activateTitle": "Activa tu cuenta de Platho",
    "quickstart.activateWhy": "La activación registra tus claves de mensajería en cadena (una tarifa única desde tu wallet). Después podrás enviar y recibir mensajes privados. Necesita una wallet con fondos: hazlo ahora o más tarde desde la pestaña Perfil.",
    "quickstart.activationNeedsChecking": "La activación necesita {fee} GRAM · comprobando saldo…",
    "quickstart.addKeyTitle": "Añade una clave de TON Center",
    "quickstart.addKeyWhy": "Tu propia clave de API gratuita de TON Center (10 solicitudes/s + el indexador de mensajes) hace que Platho sea más rápido y evita los límites de velocidad compartidos. Opcional: sin ella Platho usa el endpoint público compartido de TON Center, solo que más lento. Consigue una en ~10 segundos desde el bot de Telegram @toncenter y pégala aquí.",
    "quickstart.backupKeyTitle": "Haz una copia de tu clave de wallet",
    "quickstart.backupKeyWhy": "Dos formas de proteger la billetera. Haz al menos una.",
    "quickstart.keyFilePlateNote": "El almacenamiento del navegador puede borrarse -especialmente en Safari de iPhone-, lo que borraría tu wallet de este dispositivo. Guarda ahora el archivo de clave de wallet cifrado; está protegido por tu contraseña y también incluye tu clave de TON Center, así que puedes restaurar todo en cualquier dispositivo.",
    "quickstart.seedPlateNote": "La frase de recuperación son 24 palabras. Escrita en papel vive fuera de este dispositivo y de cualquier contraseña: aunque olvides la contraseña y pierdas el archivo, esas palabras recuperan la billetera y sus fondos en cualquier dispositivo.",
    "quickstart.saveSeedAction": "Guardar frase de recuperación",
    "quickstart.backupNeedsOne": "Guarda el archivo de clave o escribe SAVED para confirmar que anotaste las palabras. Con una basta.",
