    "quickstart.createWalletTitle": "Crea tu wallet",
    "quickstart.createWalletWhy": "Tu wallet es tu identidad y tu clave en Platho. Se genera en este dispositivo y se cifra con una contraseña que tú eliges; ningún servidor la guarda. Todo lo demás se construye sobre ella.",
    "quickstart.createYourWallet": "Crea tu wallet",
