    "quickstart.activateTitle": "Ative sua conta Platho",
    "quickstart.activateWhy": "A ativação registra suas chaves de mensagens on-chain (uma taxa única da sua carteira). Depois dela você pode enviar e receber mensagens privadas. Precisa de uma carteira com fundos - faça agora, ou depois na aba Perfil.",
    "quickstart.activationNeedsChecking": "Ativação precisa de {fee} GRAM · verificando saldo…",
    "quickstart.addKeyTitle": "Adicionar uma chave TON Center",
    "quickstart.addKeyWhy": "Sua própria chave de API gratuita do TON Center (10 requisições/seg + o indexador de mensagens) deixa o Platho mais rápido e evita limites de taxa compartilhados. Opcional - sem ela o Platho usa o endpoint público compartilhado do TON Center, só que mais lento. Obtenha uma em ~10 segundos no bot @toncenter do Telegram e cole-a aqui.",
    "quickstart.backupKeyTitle": "Faça backup da chave da sua carteira",
    "quickstart.backupKeyWhy": "Duas formas de proteger a carteira. Faça ao menos uma.",
    "quickstart.keyFilePlateNote": "O armazenamento do navegador pode ser apagado - especialmente no Safari do iPhone - o que apagaria sua carteira deste dispositivo. Salve agora o arquivo de chave da carteira criptografado; ele é protegido pela sua senha e também carrega sua chave TON Center, então você pode restaurar tudo em qualquer dispositivo.",
    "quickstart.seedPlateNote": "A frase de recuperação são 24 palavras. Escrita no papel, ela vive fora deste dispositivo e de qualquer senha: mesmo se você esquecer a senha e perder o arquivo, essas palavras trazem a carteira e os fundos de volta em qualquer dispositivo.",
    "quickstart.saveSeedAction": "Salvar frase de recuperação",
