    "welcome.publicBody": "Les publications et les commentaires sont visibles de tous, dans l’application comme dans la blockchain, en clair. Le portefeuille de l’auteur est visible également.",
    "welcome.privateTitle": "Le privé reste privé.",
    "welcome.privateBody": "Votre correspondance est chiffrée sur votre appareil : de bout en bout, avec une résistance post-quantique. Ni nous ni le réseau ne détenons les clés : seuls vous et votre correspondant pouvez la lire.",
    "welcome.responsibilityTitle": "Responsabilité",
    "welcome.responsibilityBody": "Pesez ce que vous publiez, surtout dans les fils publics. Chaque enregistrement dans la blockchain a un auteur : une publication ou un commentaire public peut engager sa responsabilité juridique selon les lois de son pays, comme toute autre publication.",
