    "quickstart.activateAction": "Konto aktivieren",
    "quickstart.activateTitle": "Aktivieren Sie Ihr Platho-Konto",
    "quickstart.activateWhy": "Die Aktivierung registriert Ihre Messaging-Schlüssel On-Chain (eine einmalige Gebühr aus Ihrer Wallet). Danach können Sie private Nachrichten senden und empfangen. Sie benötigt eine gefüllte Wallet – tun Sie es jetzt oder später über den Tab Profil.",
    "quickstart.activationNeedsChecking": "Aktivierung benötigt {fee} GRAM · Guthaben wird geprüft…",
    "quickstart.addKeyTitle": "TON Center-Schlüssel hinzufügen",
    "quickstart.addKeyWhy": "Ihr eigener kostenloser TON Center API-Schlüssel (10 Anfragen/Sek. + der Nachrichten-Indexer) macht Platho schneller und vermeidet gemeinsame Ratenlimits. Optional – ohne ihn nutzt Platho den gemeinsamen öffentlichen TON Center-Endpunkt, nur langsamer. Holen Sie sich einen in ~10 Sekunden vom @toncenter-Telegram-Bot und fügen Sie ihn hier ein.",
    "quickstart.backupKeyTitle": "Wallet-Schlüssel sichern",
    "quickstart.backupKeyWhy": "Zwei Wege, die Wallet zu sichern. Mach mindestens einen.",
    "quickstart.keyFilePlateNote": "Browser-Speicher kann gelöscht werden – besonders in iPhone Safari – wodurch Ihre Wallet von diesem Gerät entfernt würde. Speichern Sie jetzt die verschlüsselte Wallet-Schlüsseldatei; sie ist durch Ihr Passwort geschützt und enthält auch Ihren TON Center-Schlüssel, sodass Sie alles auf jedem Gerät wiederherstellen können.",
    "quickstart.seedPlateNote": "Die Wiederherstellungsphrase besteht aus 24 Wörtern. Auf Papier lebt sie außerhalb dieses Geräts und jedes Passworts: Selbst wenn du das Passwort vergisst und die Datei verlierst, holen diese Wörter die Wallet und ihr Guthaben auf jedem Gerät zurück.",
    "quickstart.saveSeedAction": "Wiederherstellungsphrase sichern",
    "quickstart.backupNeedsOne": "Speichere die Schlüsseldatei oder gib SAVED ein, um zu bestätigen, dass du die Wörter notiert hast. Eines genügt.",
    "quickstart.balanceActivationNeeds": "Wallet-Guthaben: {balance} GRAM · Aktivierung benötigt {fee} GRAM",
    "quickstart.balanceChecking": "Guthaben: wird geprüft…",
    "quickstart.checkBalance": "Guthaben prüfen",
    "quickstart.couldNotComplete": "Konnte nicht abgeschlossen werden: {reason}",
    "quickstart.couldNotCompleteLater": "Konnte nicht abgeschlossen werden – Sie können überspringen und dies später tun.",
    "quickstart.createWalletAction": "Wallet erstellen",
    "quickstart.createWalletFirst": "Erstellen Sie zuerst eine Wallet",
    "quickstart.createWalletTitle": "Erstellen Sie Ihre Wallet",
    "quickstart.createWalletWhy": "Ihre Wallet ist Ihre Identität und Ihr Schlüssel in Platho. Sie wird auf diesem Gerät erzeugt und mit einem von Ihnen gewählten Passwort verschlüsselt – kein Server hält sie jemals. Alles Weitere baut darauf auf.",
    "quickstart.createYourWallet": "Erstellen Sie Ihre Wallet",
    "quickstart.done": "Fertig",
    "quickstart.foot": "Möchten Sie lieber alles von Hand einrichten? Schließen Sie dies und nutzen Sie den Tab Profil.",
    "quickstart.getFreeKey": "Kostenlosen Schlüssel holen (@toncenter)",
    "quickstart.highlightClientDirect": "Client-direkt: kein zentraler Punkt zum Blockieren oder Zensieren",
    "quickstart.highlightEncrypted": "Ende-zu-Ende- + post-quanten-verschlüsselte private Chats",
    "quickstart.highlightOwnKeys": "Ihre eigenen Schlüssel – kein Server kann sie lesen oder halten",
    "quickstart.keyRejected": "Dieser Schlüssel wurde von TON Center abgelehnt. Prüfen Sie ihn und versuchen Sie es erneut oder überspringen Sie.",
    "quickstart.lead": "Ein Ende-zu-Ende-verschlüsselter Messenger auf TON. Ihre Schlüssel bleiben auf diesem Gerät.",
    "quickstart.language": "Sprache",
    "quickstart.notCompleted": "Nicht abgeschlossen – erneut versuchen.",
    "quickstart.notEnoughGramHint": "Nicht genug GRAM, das Konto kann noch nicht aktiviert werden. Lade die Wallet auf und nutze dann „Platho-Konto aktivieren“ im Tab Profil.",
    "quickstart.unlockToActivate": "Die Wallet ist gesperrt, das Konto kann nicht aktiviert werden. Entsperre sie und aktiviere hier oder im Tab Profil.",
    "quickstart.nothingEntered": "Nichts eingegeben – fügen Sie einen Schlüssel ein oder überspringen Sie.",
    "quickstart.pasteKeyPlaceholder": "Fügen Sie Ihren TON Center API-Schlüssel ein",
    "quickstart.pitch": "Ihre Schlüssel und Nachrichten leben nur auf diesem Gerät, verschlüsselt – es gibt kein Serverkonto, das sie lesen oder Ihre Schlüssel halten kann. Private Chats sind Ende-zu-Ende- und post-quanten-verschlüsselt; alles ist client-direkt auf TON, ohne zentrales Gateway zum Blockieren oder Zensieren.",
