    "welcome.activatedTitle": "खाता सक्रिय हो गया",
    "welcome.lead": "Platho में आपका स्वागत है। आपका वॉलेट नेटवर्क से जुड़ चुका है — आप शुरू कर सकते हैं।",
    "welcome.mission": "Platho व्यक्ति के निजी पत्राचार की गोपनीयता के अधिकार को सुनिश्चित करने के लिए बना है, और इस तरह बनाया गया है कि यह अधिकार किसी के निर्णय पर निर्भर न रहे।",
    "welcome.availableTitle": "अब क्या उपलब्ध है",
    "welcome.availablePrivate": "किसी भी सक्रिय वॉलेट के साथ निजी बातचीत",
    "welcome.availablePublic": "सार्वजनिक फ़ीड में पढ़ना और प्रकाशित करना",
    "welcome.availableComments": "वहाँ टिप्पणियाँ जहाँ लेखक ने उन्हें खुला रखा है",
    "welcome.knowTitle": "पहला संदेश भेजने से पहले जान लें",
    "welcome.irreversibleTitle": "लिखा हुआ वापस नहीं लिया जा सकता।",
    "welcome.irreversibleBody": "संदेश और पोस्ट न संपादित किए जा सकते हैं, न हटाए — वे ब्लॉकचेन में चले जाते हैं और वहाँ हमेशा रहते हैं।",
    "welcome.publicTitle": "सार्वजनिक का अर्थ है सार्वजनिक।",
    "welcome.publicBody": "पोस्ट और टिप्पणियाँ सभी को दिखती हैं — ऐप में भी और ब्लॉकचेन में भी, खुले पाठ में। लेखक का वॉलेट भी दिखता है।",
    "welcome.privateTitle": "निजी निजी ही रहता है।",
    "welcome.privateBody": "आपका पत्राचार आपके उपकरण पर एन्क्रिप्ट होता है: एंड-टू-एंड, पोस्ट-क्वांटम मजबूती के साथ। कुंजियाँ न हमारे पास हैं, न नेटवर्क के पास — पढ़ सकते हैं केवल आप और आपका वार्ताकार।",
    "welcome.responsibilityTitle": "उत्तरदायित्व",
    "welcome.responsibilityBody": "जो प्रकाशित करते हैं उसे तौलें, विशेषकर सार्वजनिक सूत्रों में। ब्लॉकचेन की हर प्रविष्टि का एक लेखक होता है: सार्वजनिक पोस्ट या टिप्पणी उसके देश के कानूनों के अनुसार उस पर कानूनी उत्तरदायित्व ला सकती है — किसी भी अन्य प्रकाशन की तरह।",
