    "quickstart.activateTitle": "अपना Platho खाता सक्रिय करें",
    "quickstart.activateWhy": "सक्रियण आपकी मैसेजिंग कुंजियों को ऑन-चेन पंजीकृत करता है (आपके वॉलेट से एक बार का शुल्क)। इसके बाद आप निजी संदेश भेज और प्राप्त कर सकते हैं। इसके लिए धनयुक्त वॉलेट चाहिए - इसे अभी करें, या बाद में Profile टैब से।",
    "quickstart.activationNeedsChecking": "सक्रियण के लिए {fee} GRAM चाहिए · बैलेंस जाँच हो रही है…",
    "quickstart.addKeyTitle": "एक TON Center कुंजी जोड़ें",
    "quickstart.addKeyWhy": "आपकी अपनी मुफ़्त TON Center API कुंजी (10 अनुरोध/सेकंड + संदेश इंडेक्सर) Platho को तेज़ बनाती है और साझा दर सीमाओं से बचाती है। वैकल्पिक - इसके बिना Platho साझा सार्वजनिक TON Center एंडपॉइंट का उपयोग करता है, बस धीमा। @toncenter Telegram बॉट से ~10 सेकंड में एक पाएँ, फिर यहाँ पेस्ट करें।",
    "quickstart.backupKeyTitle": "अपनी वॉलेट कुंजी बैकअप करें",
    "quickstart.backupKeyWhy": "वॉलेट सुरक्षित रखने के दो तरीके। कम से कम एक करें।",
    "quickstart.keyFilePlateNote": "ब्राउज़र संग्रहण मिट सकता है - खासकर iPhone Safari पर - जो इस डिवाइस से आपका वॉलेट पोंछ देगा। एन्क्रिप्टेड वॉलेट-कुंजी फ़ाइल अभी सहेजें; यह आपके पासवर्ड से सुरक्षित है और आपकी TON Center कुंजी भी साथ रखती है, ताकि आप किसी भी डिवाइस पर सब कुछ बहाल कर सकें।",
    "quickstart.seedPlateNote": "रिकवरी फ्रेज 24 शब्दों की होती है। कागज़ पर लिखी हुई यह इस डिवाइस और किसी भी पासवर्ड से बाहर रहती है: पासवर्ड भूलने और फ़ाइल खोने पर भी ये शब्द किसी भी डिवाइस पर वॉलेट और उसके फंड वापस ला देते हैं।",
    "quickstart.saveSeedAction": "रिकवरी फ्रेज सहेजें",
