    "quickstart.createWalletTitle": "अपना वॉलेट बनाएँ",
    "quickstart.createWalletWhy": "आपका वॉलेट Platho में आपकी पहचान और कुंजी है। यह इस डिवाइस पर बनता है और आपके चुने पासवर्ड से एन्क्रिप्ट होता है - कोई सर्वर इसे कभी नहीं रखता। नीचे सब कुछ इसी पर आधारित है।",
