    "quickstart.keyRejected": "वह कुंजी TON Center द्वारा अस्वीकृत हुई। इसे जाँचें और फिर से करें, या छोड़ें।",
    "quickstart.lead": "TON पर एंड-टू-एंड एन्क्रिप्टेड मैसेंजर। आपकी कुंजियाँ इसी डिवाइस पर रहती हैं।",
    "quickstart.language": "भाषा",
    "quickstart.notCompleted": "पूरा नहीं हुआ - फिर से प्रयास करें।",
