    "quickstart.pitch": "आपकी कुंजियाँ और संदेश केवल इस डिवाइस पर, एन्क्रिप्टेड रहते हैं — कोई सर्वर खाता नहीं जो उन्हें पढ़ सके या आपकी कुंजियाँ रख सके। निजी चैट एंड-टू-एंड और पोस्ट-क्वांटम एन्क्रिप्टेड हैं; सब कुछ TON पर क्लाइंट-डायरेक्ट है, अवरुद्ध या सेंसर करने के लिए कोई केंद्रीय गेटवे नहीं।",
