    "docs.unavailable": "Dokumen tidak tersedia",
    "install.body": "Platho adalah PWA statis. Setelah instalasi, cangkang aplikasi, dokumen, dan riwayat terenkripsi lokal terbatas di-cache di perangkat ini. Cache meningkatkan pemulihan, tetapi bukan cadangan universal. Akses jaringan tetap diperlukan untuk pembacaan kontrak, pembaruan feed publik terverifikasi, pengambilan riwayat pesan, dan pengiriman transaksi. Platho tidak menggunakan akun server yang bisa membaca pesan Anda atau menyimpan kunci Anda.",
    "install.bodyInstructions": "Jika Platho sudah terpasang, gunakan tombol buka-aplikasi di bilah alamat, peluncur, dock, atau daftar aplikasi. Jika belum terpasang, gunakan aksi pasang di menu peramban. Peramban tidak selalu menampilkan status aplikasi terpasang ke halaman web.",
    "install.bodyIos": "Safari tidak mengizinkan Platho membuka lembar instalasi secara langsung. Ketuk Share, pilih Add to Home Screen, lalu jalankan Platho dari Home Screen. Ia berjalan di jendela aplikasi yang lebih bersih dan tidak serapuh tab Safari biasa, tetapi tetap simpan cadangan kunci dompet terenkripsi Anda.",
    "install.bodyOpenInApp": "Peramban Anda sudah mengenali Platho sebagai aplikasi terpasang. Gunakan tombol buka-aplikasi di bilah alamat, peluncur, dock, atau daftar aplikasi untuk beralih ke jendela aplikasi terpasang.",
    "install.bodyPrompt": "Platho adalah PWA statis. Setelah instalasi, cangkang aplikasi, dokumen, dan cache riwayat terenkripsi lokal terbatas disimpan di perangkat ini. Cache meningkatkan pemulihan, tetapi bukan cadangan universal. Akses jaringan tetap diperlukan untuk pembacaan kontrak, pembaruan feed publik terverifikasi, pengambilan riwayat pesan, dan pengiriman transaksi. Platho tidak menggunakan akun server yang bisa membaca pesan Anda atau menyimpan kunci Anda.",
    "install.closePrompt": "Tutup prompt instalasi",
    "install.gotIt": "Mengerti",
    "install.help": "Jika peramban Anda tidak menampilkan lembar instalasi, gunakan menu peramban dan pilih Install app atau Add to Home screen.",
    "install.helpInstalled": "Platho sudah terpasang di perangkat ini. Buka dari layar utama, peluncur, dock, atau daftar aplikasi Anda.",
    "install.helpIos": "Mode Home Screen adalah mode iPhone yang disarankan. Jika Add to Home Screen tidak ada, pastikan halaman ini terbuka di Safari, bukan di dalam peramban aplikasi lain.",
    "install.helpOpenInApp": "Peramban tidak menyediakan API web andal yang memungkinkan Platho meluncurkan aplikasi terpasang langsung dari halaman ini.",
    "install.helpPrompt": "Langkah berikutnya membuka lembar instalasi peramban Anda. Jika Anda membatalkannya, tombol pasang tetap di sini agar Anda masih bisa menemukan jalur manualnya.",
    "install.helpTextAndroid": "Di Android Chrome, buka menu peramban dan pilih Install app atau Add to Home screen.",
    "install.helpTextDesktop": "Di Chrome atau Edge, gunakan ikon pasang di bilah alamat atau menu peramban: Apps / Install this site.",
    "install.helpTextIos": "Di iPhone atau iPad, buka halaman ini di Safari, ketuk Share, lalu Add to Home Screen.",
