    "quickstart.activateAction": "Aktifkan akun",
    "quickstart.activateTitle": "Aktifkan akun Platho Anda",
    "quickstart.activateWhy": "Aktivasi mendaftarkan kunci pesan Anda on-chain (biaya sekali dari dompet Anda). Setelahnya Anda bisa mengirim dan menerima pesan privat. Ini butuh dompet yang berdana - lakukan sekarang, atau nanti dari tab Profil.",
    "quickstart.activationNeedsChecking": "Aktivasi butuh {fee} GRAM · memeriksa saldo…",
    "quickstart.addKeyTitle": "Tambahkan kunci TON Center",
    "quickstart.addKeyWhy": "Kunci API TON Center gratis milik Anda sendiri (10 permintaan/detik + pengindeks pesan) membuat Platho lebih cepat dan menghindari batas laju bersama. Opsional - tanpanya Platho memakai endpoint TON Center publik bersama, hanya lebih lambat. Dapatkan dalam ~10 detik dari bot Telegram @toncenter, lalu tempelkan di sini.",
    "quickstart.backupKeyTitle": "Cadangkan kunci dompet Anda",
    "quickstart.backupKeyWhy": "Dua cara menjaga dompet. Lakukan setidaknya satu.",
    "quickstart.keyFilePlateNote": "Penyimpanan browser bisa dihapus - terutama di iPhone Safari - yang akan menghapus dompet Anda dari perangkat ini. Simpan file kunci dompet terenkripsi sekarang; dilindungi kata sandi Anda dan juga membawa kunci TON Center Anda, sehingga Anda bisa memulihkan semuanya di perangkat mana pun.",
    "quickstart.seedPlateNote": "Frasa pemulihan terdiri dari 24 kata. Ditulis di kertas, ia hidup di luar perangkat ini dan di luar kata sandi apa pun: meski Anda lupa kata sandi dan kehilangan berkas, kata-kata itu mengembalikan dompet dan dananya di perangkat mana pun.",
    "quickstart.saveSeedAction": "Simpan frasa pemulihan",
    "quickstart.backupNeedsOne": "Simpan berkas kunci, atau ketik SAVED untuk memastikan Anda sudah mencatat kata-katanya. Salah satu cukup.",
    "quickstart.balanceActivationNeeds": "Saldo dompet: {balance} GRAM · aktivasi butuh {fee} GRAM",
