    "quickstart.createWalletAction": "Buat dompet",
    "quickstart.createWalletFirst": "Buat dompet dulu",
    "quickstart.createWalletTitle": "Buat dompet Anda",
    "quickstart.createWalletWhy": "Dompet Anda adalah identitas dan kunci Anda di Platho. Ia dibuat di perangkat ini dan dienkripsi dengan kata sandi pilihan Anda - tidak ada server yang menyimpannya. Semua di bawah ini dibangun di atasnya.",
    "quickstart.createYourWallet": "Buat dompet Anda",
