    "quickstart.keyRejected": "Kunci itu ditolak oleh TON Center. Periksa dan coba lagi, atau Lewati.",
    "quickstart.lead": "Messenger terenkripsi end-to-end di TON. Kunci Anda tetap di perangkat ini.",
    "quickstart.language": "Bahasa",
    "quickstart.notCompleted": "Belum selesai - coba lagi.",
    "quickstart.notEnoughGramHint": "GRAM tidak cukup, jadi akun belum bisa diaktifkan. Isi ulang dompet, lalu gunakan “Aktifkan akun Platho” di tab Profil.",
    "quickstart.unlockToActivate": "Dompet terkunci, jadi akun tidak bisa diaktifkan. Buka kuncinya, lalu aktifkan di sini atau di tab Profil.",
