    "quickstart.pitch": "Kunci dan pesan Anda hanya ada di perangkat ini, terenkripsi — tidak ada akun server yang bisa membacanya atau menyimpan kunci Anda. Chat privat terenkripsi end-to-end dan pasca-kuantum; semuanya langsung dari klien di TON, tanpa gerbang pusat untuk diblokir atau disensor.",
