    "quickstart.activateTitle": "Platho アカウントを有効化",
    "quickstart.activateWhy": "有効化するとメッセージング用のキーがオンチェーンに登録されます（ウォレットから一度だけ手数料がかかります）。その後、非公開メッセージの送受信ができます。資金のあるウォレットが必要です — 今すぐ行うか、後で Profile タブから行ってください。",
    "quickstart.activationNeedsChecking": "有効化には {fee} GRAM が必要 · 残高を確認中…",
    "quickstart.addKeyTitle": "TON Center キーを追加",
    "quickstart.addKeyWhy": "自分専用の無料 TON Center API キー（毎秒 10 リクエスト + メッセージインデクサー）は Platho を高速化し、共有のレート制限を回避します。任意です — なくても Platho は共有の公開 TON Center エンドポイントを使いますが、遅くなります。@toncenter Telegram ボットから約 10 秒で取得し、ここに貼り付けてください。",
    "quickstart.backupKeyTitle": "ウォレットキーをバックアップ",
    "quickstart.backupKeyWhy": "ウォレットを守る方法は二つ。少なくとも一つは行ってください。",
    "quickstart.keyFilePlateNote": "ブラウザのストレージは消去されることがあり（特に iPhone Safari）、このデバイスからウォレットが消えてしまう可能性があります。暗号化されたウォレットキーファイルを今すぐ保存してください。パスワードで保護され、TON Center キーも含まれるため、どのデバイスでもすべてを復元できます。",
    "quickstart.seedPlateNote": "リカバリーフレーズは 24 単語です。紙に書けばこの端末とパスワードの外側に残り、パスワードを忘れファイルを失っても、どの端末でもウォレットと資金を取り戻せます。",
    "quickstart.saveSeedAction": "リカバリーフレーズを保存",
